mapper.select:
select bcci.id, bcci.api_code, bcci.cust_num as custNum, DATE_FORMAT(bcci.create_time, '%Y-%m-%d') as appletDate, bcci.resource_type as resourceType, bcci.clue_id as clueId, bcci.clue_data_status as clueDataStatus, bcci.clue_complete_status as clueCompleteStatus, bcci.intention, CASE WHEN bcci.clue_data_status = 1 THEN bcci.clue_match_brand ELSE bcci.brand END AS brand, CASE WHEN bcci.clue_data_status = 1 THEN bcci.clue_match_series ELSE bcci.series END AS series, CASE WHEN bcci.clue_data_status = 1 THEN bcci.clue_match_city ELSE bcci.city END AS city, bcci.cell, DATE_FORMAT(bcci.clean_time, '%Y-%m-%d %H:%i:%s') as cleanTime, DATE_FORMAT(bcci.update_time, '%Y-%m-%d %H:%i:%s') as updateTime, bcci.clue_push_channel as cluePushChannel, bcci.clue_push_status as cluePushStatus, DATE_FORMAT(bcci.push_time, '%Y-%m-%d %H:%i:%s') as pushTime, DATE_FORMAT(bcci.call_back_time, '%Y-%m-%d %H:%i:%s') as callBackTime, bcci.clue_callback_final_state as clueCallbackFinalState, bcci.recording_path as recordingPath, bcci.call_dialog as callDiaLog, bcci.resource_type as resourceType, bcci.call_id as callId, bcci.clue_error_reason as clueErrorReason from b_car_clue_info bcci
and bcci.create_time >= #{createTimeStart}
and bcci.create_time < #{createTimeEnd}
and bcci.resource_type = #{resourceType}
and bcci.intention = #{intention}
AND bcci.clue_data_status IN
#{clueDataStatus}
AND bcci.clue_complete_status IN
#{clueCompleteStatus}
and bcci.update_time >= #{updateTimeStart}
and bcci.update_time < #{updateTimeEnd}
AND (bcci.clue_push_channel IS NULL OR bcci.clue_push_channel = '')
AND bcci.clue_push_channel IN
#{channel}
and bcci.clue_push_status = #{cluePushStatus}
and bcci.push_time >= #{pushTimeStart}
and bcci.push_time < #{pushTimeEnd}
and bcci.clue_callback_final_state = #{status}
and bcci.call_back_time >= #{callBackTimeStart}
and bcci.call_back_time < #{callBackTimeEnd}
and (bcci.brand like concat("%", #{search},"%") or bcci.series like concat("%", #{search},"%") or bcci.city like concat("%", #{search},"%") or bcci.clue_match_brand like concat("%", #{search},"%") or bcci.clue_match_series like concat("%", #{search},"%") or bcci.clue_match_city like concat("%", #{search},"%"))
order by ${orderByField} ${orderByType}

select *
from b_car_clue_info
where api_code IN

    #{apicode}

and clue_data_status = #{status}

    and `id` > #{minId}

order by `id` asc limit 2000

select *
from b_car_clue_info


         and create_time >= #{carClueReportDTO.createTimeStart} 


         and create_time < #{carClueReportDTO.createTimeEnd} 


        and resource_type = #{carClueReportDTO.resourceType}


        and intention = #{carClueReportDTO.intention}


        AND clue_data_status IN

            #{clueDataStatus}



        AND clue_complete_status IN

            #{clueCompleteStatus}



         and update_time >= #{carClueReportDTO.updateTimeStart} 


         and update_time < #{carClueReportDTO.updateTimeEnd} 


        AND clue_push_channel IN

            #{channel}



        and clue_push_status = #{carClueReportDTO.cluePushStatus}


         and push_time >= #{carClueReportDTO.pushTimeStart} 


         and push_time < #{carClueReportDTO.pushTimeEnd} 


        and clue_callback_final_state = #{carClueReportDTO.clueCallbackFinalState}


         and call_back_time >= #{carClueReportDTO.callBackTimeStart} 


         and call_back_time < #{carClueReportDTO.callBackTimeEnd} 


        and (brand like concat("%", #{carClueReportDTO.search},"%")
        or series like concat("%", #{carClueReportDTO.search},"%")
        or city like concat("%", #{carClueReportDTO.search},"%")
        or clue_match_brand like concat("%", #{carClueReportDTO.search},"%")
        or clue_match_series like concat("%", #{carClueReportDTO.search},"%")
        or clue_match_city like concat("%", #{carClueReportDTO.search},"%"))


        and `id` > #{minId}


order by `id` asc limit 2000
